IF OBJECT_ID('tempdb..#ImportOrgEvents') IS NOT NULL DROP TABLE #ImportOrgEvents;
CREATE TABLE #ImportOrgEvents (
  RowNum INT,
  OrgNameHint NVARCHAR(500) COLLATE DATABASE_DEFAULT,
  RegNum INT, RegYear INT,
  Level NVARCHAR(50) COLLATE DATABASE_DEFAULT,
  Governorate NVARCHAR(100) COLLATE DATABASE_DEFAULT,
  IncomingNum NVARCHAR(100) COLLATE DATABASE_DEFAULT,
  IncomingDate DATE, EventDate DATE,
  Receiver NVARCHAR(200) COLLATE DATABASE_DEFAULT,
  Subject NVARCHAR(1000) COLLATE DATABASE_DEFAULT,
  Status NVARCHAR(50) COLLATE DATABASE_DEFAULT,
  Actions NVARCHAR(MAX) COLLATE DATABASE_DEFAULT
);
GO

