-- ── خطوة 1: إضافة الجمعيات الناقصة بحالة "تحتاج مراجعة" (نفس منطق checkRegNumDuplicate بالظبط) ──
INSERT INTO Organizations (OrgName, OrgType, RegNum, RegYear, Level, Governorate, Status, Notes, IsActive, CreatedAt)
SELECT DISTINCT s.OrgNameHint, 
  CASE WHEN s.OrgNameHint LIKE N'مؤسسة%' THEN N'مؤسسة' WHEN s.OrgNameHint LIKE N'اتحاد%' THEN N'اتحاد' ELSE N'جمعية' END,
  s.RegNum, s.RegYear, s.Level, s.Governorate,
  N'تحتاج مراجعة',
  N'أُضيفت تلقائيًا من استيراد سجل آخر حدث - شهر 7/2026. تحتاج استكمال بيانات (رئيس مجلس الإدارة، الهاتف، العنوان..) عند توفرها.',
  1, GETDATE()
FROM #ImportOrgEvents s
WHERE NOT EXISTS (
  SELECT 1 FROM Organizations o
  WHERE (s.Level = N'مركزي' AND o.Level = N'مركزي' AND o.RegNum = s.RegNum)
     OR (s.Level = N'مديرية' AND o.Level = N'مديرية' AND o.RegNum = s.RegNum
         AND ISNULL(o.Governorate,N'') = ISNULL(s.Governorate,N''))
);
GO

-- ── تقرير: الجمعيات اللي اتضافت جديدة بحالة "تحتاج مراجعة" (راجعيها لاستكمال بياناتها) ──
SELECT o.OrgID, o.OrgName, o.RegNum, o.RegYear, o.Level, o.Governorate, o.Status
FROM Organizations o
WHERE o.Notes = N'أُضيفت تلقائيًا من استيراد سجل آخر حدث - شهر 7/2026. تحتاج استكمال بيانات (رئيس مجلس الإدارة، الهاتف، العنوان..) عند توفرها.'
ORDER BY o.OrgID;
GO

-- ── خطوة 2: مطابقة كل صف مع الجمعية (موجودة أصلاً أو المُضافة للتو) بنفس منطق checkRegNumDuplicate ──
IF OBJECT_ID('tempdb..#OrgMatch') IS NOT NULL DROP TABLE #OrgMatch;
SELECT s.*, m.OrgID, m.OrgName AS MatchedOrgName
INTO #OrgMatch
FROM #ImportOrgEvents s
OUTER APPLY (
  SELECT TOP 1 o.OrgID, o.OrgName FROM Organizations o
  WHERE o.IsActive = 1
    AND ((s.Level = N'مركزي' AND o.Level = N'مركزي' AND o.RegNum = s.RegNum)
      OR (s.Level = N'مديرية' AND o.Level = N'مديرية' AND o.RegNum = s.RegNum
          AND ISNULL(o.Governorate,N'') = ISNULL(s.Governorate,N'')))
) m;
GO

-- ── تقرير: أي صف (نادر جدًا/غير متوقع) لسه من غير OrgID بعد خطوة الإضافة - يستاهل تدقيق يدوي ──
SELECT * FROM #OrgMatch WHERE OrgID IS NULL;
GO

-- ── خطوة 3: التسجيل الفعلي لأحداث الجمعيات ──
INSERT INTO OrgEvents (OrgID, EventType, Subject, EventDate, Department, RecordedBy,
  IncomingNum, IncomingDate, Receiver, Actions, Status, IsImportant, IsUrgent)
SELECT OrgID, N'خطاب', Subject, EventDate, N'جمع المال', NULL,
  IncomingNum, IncomingDate, Receiver, Actions, Status, 0, 0
FROM #OrgMatch WHERE OrgID IS NOT NULL;
GO

PRINT N'✅ تم استيراد سجلات أحداث الجمعيات بنجاح (بما فيها الجمعيات الجديدة تحت المراجعة).';
GO

