-- ══ تحقق فعلي نهائي (متعتمديش على رسايل ✅ اللي فوق - دي بتتطبع دايمًا حتى لو
--    فشلت الخطوة اللي قبلها في GO منفصل. الأرقام تحت هي الدليل الحقيقي) ══
SELECT COUNT(*) AS OrgEventsImportedJustNow FROM OrgEvents
WHERE Department = N'جمع المال' AND EventType = N'خطاب' AND CreatedAt >= DATEADD(MINUTE,-10,GETDATE());
GO
SELECT COUNT(*) AS OtherPartyEventsImportedJustNow FROM OtherPartyEvents
WHERE Department = N'جمع المال' AND EventType = N'خطاب' AND CreatedAt >= DATEADD(MINUTE,-10,GETDATE());
GO

